SELECT
	*
FROM
	SHOPPING_BEHAVIOR
LIMIT
	10;

-- Business queries 
-- Q1: What is the total revenue generated by male vs female customers
SELECT
	GENDER,
	SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE
FROM
	SHOPPING_BEHAVIOR
GROUP BY
	GENDER;

-- Q2: Which customers used discounts but still spent more than the average purchase amount
SELECT
	CUSTOMER_ID,
	PURCHASE_AMOUNT
FROM
	SHOPPING_BEHAVIOR
WHERE
	DISCOUNT_APPLIED = 'Yes'
	AND PURCHASE_AMOUNT >= (
		SELECT
			AVG(PURCHASE_AMOUNT)
		FROM
			SHOPPING_BEHAVIOR
	);

-- Q3: Which are the top 5 products with the highest average review rating?
SELECT
	ITEM_PURCHASED,
	ROUND(AVG(REVIEW_RATING::NUMERIC), 2) AS AVERAGE_PRODUCT_RATING
FROM
	SHOPPING_BEHAVIOR
GROUP BY
	ITEM_PURCHASED
ORDER BY
	AVERAGE_PRODUCT_RATING DESC
LIMIT
	5;

-- Q4: Compare the average purchase amounts between standard and express shipping
SELECT
	SHIPPING_TYPE,
	ROUND(AVG(PURCHASE_AMOUNT), 2)
FROM
	SHOPPING_BEHAVIOR
WHERE
	SHIPPING_TYPE IN ('Standard', 'Express')
GROUP BY
	SHIPPING_TYPE;

-- Q5: Do subscribed customers spend more? 
-- Compare the average spend between and total revenue from subscribers and non-subscribers
SELECT
	SUBSCRIPTION_STATUS,
	ROUND(AVG(PURCHASE_AMOUNT), 2) AS AVERAGE_SPEND,
	SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE
FROM
	SHOPPING_BEHAVIOR
GROUP BY
	SUBSCRIPTION_STATUS
ORDER BY
	AVERAGE_SPEND,
	TOTAL_REVENUE;

-- Q6: What 5 products have the highest percentage of purchases with discounts applied?
SELECT
	ITEM_PURCHASED,
	COUNT(ITEM_PURCHASED) AS DISCOUNTED_ITEMS_COUNT,
	ROUND(
		(
			COUNT(ITEM_PURCHASED) * 100.0 / (
				SELECT
					COUNT(ITEM_PURCHASED)
				FROM
					SHOPPING_BEHAVIOR
			)
		),
		2
	) AS DISCOUNTED_ITEMS_PERCENTAGE
FROM
	SHOPPING_BEHAVIOR
WHERE
	DISCOUNT_APPLIED = 'Yes'
GROUP BY
	ITEM_PURCHASED
ORDER BY
	2 DESC
LIMIT
	5;

-- Q7: Segment the customers into 'New,' 'Returning,' and 'Loyal' based on their total number of previous purchases 
-- and show the count of each segmentation.
WITH
	CUSTOMER_TYPE AS (
		SELECT
			CUSTOMER_ID,
			PREVIOUS_PURCHASES,
			CASE
				WHEN PREVIOUS_PURCHASES = 1 THEN 'New'
				WHEN PREVIOUS_PURCHASES BETWEEN 2 AND 10  THEN 'Returning'
				ELSE 'Loyal'
			END AS CUSTOMER_SEGMENTS
		FROM
			SHOPPING_BEHAVIOR
	)
SELECT
	CUSTOMER_SEGMENTS,
	COUNT(*) AS NUMBER_OF_CUSTOMERS
FROM
	CUSTOMER_TYPE
GROUP BY
	CUSTOMER_SEGMENTS
ORDER BY
	2 DESC;

-- Q8: What are the top 3 most purchased products within each category?
WITH
	ITEM_COUNTS AS (
		SELECT
			CATEGORY,
			ITEM_PURCHASED,
			COUNT(CUSTOMER_ID) AS TOTAL_ORDERS,
			ROW_NUMBER() OVER (
				PARTITION BY
					CATEGORY
				ORDER BY
					COUNT(CUSTOMER_ID) DESC
			) AS ITEM_RANK
		FROM
			SHOPPING_BEHAVIOR
		GROUP BY
			CATEGORY,
			ITEM_PURCHASED
	)
SELECT
	ITEM_RANK,
	CATEGORY,
	ITEM_PURCHASED,
	TOTAL_ORDERS
FROM
	ITEM_COUNTS
WHERE
	ITEM_RANK <= 3;

-- Q9: Are customer who are classified as 'returning' customers also likely to subscribe?
SELECT
	SUBSCRIPTION_STATUS,
	COUNT(CUSTOMER_ID) AS NUMBER_OF_RETURN_CUSTOMERS
FROM
	SHOPPING_BEHAVIOR
WHERE
	PREVIOUS_PURCHASES > 5
GROUP BY
	SUBSCRIPTION_STATUS;

-- Q10: What is the revenue contribution of each age group?
SELECT
	AGE_GROUP,
	SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUES
FROM
	SHOPPING_BEHAVIOR
GROUP BY
	AGE_GROUP
ORDER BY
	2 DESC;